// IAN gave meetings for these two. investor_response is already set by the team ('meeting');
// this adds the structured date so the meeting is queryable and 'meeting-stage' skipping is explicit.
const MEET = [
  { deal_id: 'D00056', startup: 'Luxova', date: '2026-09-15', half: 'second half' },
  { deal_id: 'D01761', startup: 'Nexcore', date: '2026-09-15', half: 'first half' }
];
function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const out = [];
for (const m of MEET) {
  const hits = rows.filter(function (r) { return s(r.deal_id) === m.deal_id; });
  if (hits.length !== 1) { throw new Error('ABORT: expected 1 row for ' + m.deal_id + ', found ' + hits.length); }
  const h = hits[0];
  if (s(h.startup) !== m.startup) { throw new Error('ABORT: ' + m.deal_id + ' is ' + s(h.startup) + ', not ' + m.startup); }
  if (s(h.investor).toLowerCase().indexOf('ian group') !== 0) { throw new Error('ABORT: ' + m.deal_id + ' is not an IAN row'); }
  const prev = s(h.notes);
  out.push({ json: {
    deal_id: m.deal_id,
    meeting_scheduled: 'Yes',
    meeting_date: m.date,
    deal_status: 'Meeting scheduled',
    notes: (prev ? prev + ' | ' : '') + 'IAN meeting ' + m.date + ' (' + m.half + ')'
  }});
}
return out;

// Deal Tracker row 212 shows EosNox as IAN's latest deal shared (last mail 2026-08-31, status
// 'Meeting Scheduled'), but PIPELINE has no row for the pair at all. Create it as already-shared
// so the meeting is recorded AND future match runs cannot re-pitch it.
function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const dupe = rows.filter(function (r) {
  return s(r.startup).toLowerCase() === 'eosnox' && s(r.investor).toLowerCase().indexOf('ian group') === 0;
});
if (dupe.length > 0) { throw new Error('ABORT: an IAN <> EosNox row already exists (' + s(dupe[0].deal_id) + ')'); }

let maxN = 0;
for (const r of rows) {
  const id = s(r.deal_id);
  if (id.charAt(0) === 'D') { const n = parseInt(id.slice(1), 10); if (!isNaN(n) && n > maxN) { maxN = n; } }
}
if (maxN === 0) { throw new Error('ABORT: could not determine max deal_id'); }

let own = '';
for (const r of rows) { if (s(r.startup) === 'EosNox' && s(r.owner)) { own = s(r.owner); break; } }
if (!own) { throw new Error('ABORT: could not determine owner for EosNox'); }

let pad = String(maxN + 1);
while (pad.length < 5) { pad = '0' + pad; }
return [{ json: {
  deal_id: 'D' + pad,
  startup: 'EosNox',
  owner: own,
  investor: 'IAN Group - Angel Fund',
  email: 'brendon@iangroup.vc',
  cc: '',
  priority: 0,
  deal_shared: 'Yes',
  date_shared: '2026-08-31',
  channel: 'Email',
  last_contact: '2026-08-31',
  next_action: 'Meeting scheduled',
  next_due: '',
  investor_response: 'meeting',
  meeting_scheduled: 'Yes',
  meeting_date: '2026-09-09',
  deal_status: 'Meeting scheduled',
  notes: 'Backfilled 2026-09-07 from Deal Tracker row 212: shared to IAN (last mail 2026-08-31), meeting 2026-09-09'
}}];
